const clave = ([ruta, huella]) => new URL(`${ruta}?h=${huella}`, self.location).href;

self.addEventListener('install', ev => {
  ev.waitUntil((async () => {
    const nuevo = await caches.open(CACHE);
    const viejos = (await caches.keys()).filter(k => k.startsWith('guia-serpientes-') && k !== CACHE);
    const pendientes = [...ARCHIVOS];
    const trabajar = async () => {
      for (let a = pendientes.shift(); a; a = pendientes.shift()) {
        const url = clave(a);
        let r = null;
        for (const k of viejos) { r = await (await caches.open(k)).match(url); if (r) break; }
        if (!r) {
          r = await fetch(url, { cache: 'no-cache' });
          if (!r.ok) throw new Error(`No se pudo bajar ${a[0]}`);
        }
        await nuevo.put(url, r);
      }
    };
    await Promise.all(Array.from({ length: 8 }, trabajar));
    await self.skipWaiting();
  })());
});

self.addEventListener('activate', ev => {
  ev.waitUntil((async () => {
    for (const k of await caches.keys()) if (k.startsWith('guia-serpientes-') && k !== CACHE) await caches.delete(k);
    await self.clients.claim();
  })());
});

self.addEventListener('fetch', ev => {
  const req = ev.request;
  if (req.method !== 'GET' || new URL(req.url).origin !== self.location.origin) return;
  if (new URL(req.url).pathname.endsWith('/version-web.json')) return;   // «Buscar actualización»: siempre de internet
  ev.respondWith((async () => {
    const cache = await caches.open(CACHE);
    const pedido = req.mode === 'navigate' ? new URL('index.html', self.location).href : req.url;
    return (await cache.match(pedido, { ignoreSearch: true })) || fetch(req);
  })());
});
